"""Units-mode strings for all 30 Kiln locales."""

def pack(files, units, swap, copy, refresh, updated, stale, offline, auto, currency, privacy, cats):
    keys = {
        "workspace.files": files,
        "workspace.units": units,
        "units.swap": swap,
        "units.copy": copy,
        "units.refresh": refresh,
        "units.updated": updated,
        "units.stale": stale,
        "units.offline": offline,
        "units.auto_refresh": auto,
        "settings.currency": currency,
        "settings.currency.privacy": privacy,
    }
    names = [
        "angle", "area", "currency", "data", "energy", "force", "fuel", "length",
        "power", "pressure", "speed", "temperature", "time", "volume", "weight",
        "frequency", "acceleration", "illuminance",
    ]
    for name, label in zip(names, cats):
        keys[f"category.{name}"] = label
    return keys


